+				break;
+			case "vertex":
+				visitVertex(target.id);
+				break;
+			case "edge":
+				visitEdge(target.id);
+				break;
+			case "wire":
+				visitWire(target.id);
+				break;
+			case "face":
+				visitFace(target.id);
+				break;
+			case "shell":
